const TOKEN='0x'+'11'.repeat(20),OTHER='0x'+'22'.repeat(20),SETTLER='0x'+'33'.repeat(20),PREVIOUS='0x'+'44'.repeat(20),HOLDER='0x0000000000001ff3684f28c67538d4d072c22734',REGISTRY='0x00000000000004533fe15556b1e086bb1a72ceae';
const owner=Wallet.createRandom(),foreign=Wallet.createRandom(),headers:Record<string,string>={'X-AgentBazaar':'1'};
let pg:PGlite,socket:PGLiteSocketServer,db:any,app:any,client:any,other:any,userId:string,channel:any,execute:any,providers:any,access:any,ops:any,tradeAddress:string,instanceId:string,ip=0;
const limits={kind:'TRADE',tokenScope:'ANY_ROBINHOOD',tokens:[],perLimitEth:'0.01',dailyEth:'0.03',maxFeeEth:'0.001',slippageBps:100,durationHours:24,consent:true};
const post=(path:string,body:any={})=>client.post('/api/robinhood'+path).set(headers).send(body);
async function login(agent:any,wallet:Wallet|ReturnType<typeof Wallet.createRandom>){const proof=await agent.post('/api/auth/wallet/challenge').set(headers).send({address:wallet.address,chainId:4663});expect(proof.status).toBe(200);expect((await agent.post('/api/auth/wallet/verify').set(headers).send({signature:await wallet.signMessage(proof.body.message)})).status).toBe(200);return (await agent.get('/api/bootstrap')).body.user.id;}
async function grant(change:any={}){const review=await post('/permission/review',{...limits,...change});expect(review.status,JSON.stringify(review.body)).toBe(200);expect(review.body.message).toContain('Chain ID: 4663');const result=await post('/permission/approve',{kind:change.kind||'TRADE',id:review.body.id,signature:await owner.signMessage(review.body.message)});expect(result.status,JSON.stringify(result.body)).toBe(200);return review.body.id;}
async function chat(text:string,id:string=randomUUID()){return execute(userId,text,'WHATSAPP',id,new Date(),{id:channel.id,ownerId:'user:owner',leaseToken:'lease'});}
async function secondChannel(){const {encrypt}=await import('../server/security.js');return db.personalAgentChannel.create({data:{userId,slot:2,label:'Second agent',encryptedToken:encrypt('private-second-whatsapp-key'),tokenFingerprint:'second-fixture',ownerId:'user:second',consentAt:new Date(),createdAt:new Date(Date.now()-1000),leaseToken:'lease-second',leaseUntil:new Date(Date.now()+3600000)}});}
const secondChat=(c:any,text:string,id:string=randomUUID())=>execute(userId,text,'WHATSAPP',id,new Date(),{id:c.id,ownerId:c.ownerId,leaseToken:c.leaseToken});
function encodeQuote(taker=tradeAddress,side='BUY',amount='1000000000000000',minimum='990000',changes:any={}){
  const selected=changes.token||TOKEN,{holderAbi,settlerAbi}=providers,buy=side==='BUY'?selected:ETH_TOKEN,sell=side==='BUY'?ETH_TOKEN:selected;
  let data=settlerAbi.encodeFunctionData('execute',[[changes.recipient||taker,changes.output||buy,changes.minimum||minimum],['0x12345678'],'0x'+'00'.repeat(32)]);
  const settler=changes.settler||SETTLER,envelope=side==='SELL'||changes.holderBuy;
  if(envelope)data=holderAbi.encodeFunctionData('exec',[changes.operator||settler,sell,changes.input||amount,settler,data]);
  return {liquidityAvailable:true,sellToken:sell,buyToken:buy,sellAmount:amount,buyAmount:side==='BUY'?'1000000':'1000000000000000',minBuyAmount:minimum,transaction:{to:envelope?HOLDER:settler,data,value:side==='BUY'?amount:'0'},issues:{allowance:side==='SELL'?{spender:HOLDER}:null,simulationIncomplete:false},fees:{zeroExFee:null,integratorFee:null},...changes.raw};
}
function provider(options:{unknown?:boolean;approvalUnknown?:boolean;badMinimum?:boolean;feeTooHigh?:boolean;wrongChain?:boolean;balance?:bigint;tokenBalance?:bigint;ownerPending?:boolean;estimateError?:string;estimateErrorCode?:number;estimateErrorData?:string;requireGasBounds?:boolean;noLiquidity?:boolean;quoteBalanceIssue?:boolean;malformedQuote?:boolean;simulationRevert?:boolean;onNonce?:()=>Promise<void>;quoteSettler?:string;currentSettler?:string;previousSettler?:string;holderBuy?:boolean;registryPaused?:boolean;badRegistry?:boolean;prevUnavailable?:boolean}={}){
  const erc20=providers.erc20,registryAbi=new Interface(['function ownerOf(uint256) view returns(address)','function prev(uint128) view returns(address)']);let nonce=0,approved=false,sends=0,swapSends=0;const signatures=new Map<string,any>();
  const fetchMock=vi.fn(async(url:any,init:any={}):Promise<Response>=>{
    if(String(url).startsWith('https://api.0x.org/')){if(options.noLiquidity)return Response.json({liquidityAvailable:false,zid:'fixture'});if(options.malformedQuote)return Response.json({liquidityAvailable:true});const p=new URL(url).searchParams;const side=p.get('sellToken')===ETH_TOKEN?'BUY':'SELL',amount=p.get('sellAmount')!,minimum=side==='BUY'?'990000':'990000000000000';let quote=encodeQuote(p.get('taker')!,side,amount,minimum,{token:p.get(side==='BUY'?'buyToken':'sellToken'),minimum:options.badMinimum?'1':minimum,settler:options.quoteSettler,holderBuy:options.holderBuy});if(approved)quote.issues.allowance=null as any;if(options.quoteBalanceIssue)(quote.issues as any).balance={actual:'0',expected:amount,token:p.get('sellToken')};if(options.feeTooHigh)quote.fees.zeroExFee={amount:'20000',token:side==='BUY'?TOKEN:ETH_TOKEN} as any;return Response.json(quote);}
    if(String(url).startsWith('https://api.dexscreener.com/')){if(String(url).includes('token-profiles'))return Response.json([{chainId:'robinhood',tokenAddress:TOKEN},{chainId:'solana',tokenAddress:'invalid'}]);return Response.json([{chainId:'robinhood',pairAddress:OTHER,dexId:'uniswap',baseToken:{address:TOKEN,name:'Test token',symbol:'TST'},priceUsd:'2',liquidity:{usd:50000},volume:{h24:100000},priceChange:{h24:5},pairCreatedAt:Date.now()-1000}]);}
    const payload=JSON.parse(init.body||'{}'),[arg]=payload.params||[];let result:any;switch(payload.method){
      case 'eth_chainId':result=options.wrongChain?'0x1':'0x1237';break;
      case 'eth_getBalance':result='0x'+(options.balance??10n**18n).toString(16);break;
      case 'eth_gasPrice':result='0x3b9aca00';break;
      case 'eth_estimateGas':if(options.requireGasBounds&&(!arg.gas||!arg.gasPrice))return Response.json({jsonrpc:'2.0',id:1,error:{code:-32000,message:'default gas allowance cannot be funded'}});if(options.estimateError)return Response.json({jsonrpc:'2.0',id:1,error:{code:options.estimateErrorCode??-32000,message:options.estimateError,data:options.estimateErrorData}});result='0x5208';break;
      case 'eth_getTransactionCount':if(options.onNonce)await options.onNonce();result='0x'+(options.ownerPending&&String(arg).toLowerCase()===owner.address.toLowerCase()&&payload.params[1]==='pending'?nonce+1:nonce).toString(16);break;
      case 'eth_call':{
        if(options.simulationRevert&&arg.gas)return Response.json({jsonrpc:'2.0',id:1,error:{code:3,message:'execution reverted: private upstream details'}});
        if(arg.to?.toLowerCase()===REGISTRY){const method=registryAbi.parseTransaction({data:arg.data})!;expect(method.args[0]).toBe(2n);if(method.name==='ownerOf'&&options.registryPaused||method.name==='prev'&&options.prevUnavailable)return Response.json({jsonrpc:'2.0',id:1,error:{code:3,message:'Registry unavailable'}});result=options.badRegistry?'0x':registryAbi.encodeFunctionResult(method.name,[method.name==='ownerOf'?options.currentSettler||SETTLER:options.previousSettler||PREVIOUS]);break;}
        if(arg.data==='0x'){result='0x';break;}
        const parsed=erc20.parseTransaction({data:arg.data});
        if(parsed?.name==='decimals')result=erc20.encodeFunctionResult('decimals',[6]);
        else if(parsed?.name==='symbol')result=erc20.encodeFunctionResult('symbol',['TST']);
        else if(parsed?.name==='name')result=erc20.encodeFunctionResult('name',['Test token']);
        else if(parsed?.name==='allowance')result=erc20.encodeFunctionResult('allowance',[approved?2n**128n:0]);
        else if(parsed?.name==='balanceOf')result=erc20.encodeFunctionResult('balanceOf',[options.tokenBalance??200000000n]);
        else result='0x';break;
      }
      case 'alchemy_getTokenBalances':result={tokenBalances:[{contractAddress:TOKEN,tokenBalance:'0xf4240'}]};break;
      case 'eth_sendRawTransaction':{sends++;const tx=Transaction.from(arg);expect(tx.chainId).toBe(4663n);expect(tx.from?.toLowerCase()).toBe(tradeAddress);const signature=keccak256(arg),approval=tx.to?.toLowerCase()===TOKEN&&tx.data.startsWith(erc20.getFunction('approve')!.selector);if(!approval)swapSends++;if(approval)approved=true;nonce++;signatures.set(signature,{approval,tx});if(options.unknown||options.approvalUnknown&&approval)throw Error('Simulated ambiguous submission');result=signature;break;}
      case 'eth_getTransactionReceipt':{const sent=signatures.get(arg);let logs:any[]=[];if(sent&&!sent.approval&&sent.tx.data!=='0x'){try{const envelope=sent.tx.to.toLowerCase()===HOLDER?providers.holderAbi.decodeFunctionData('exec',sent.tx.data):null,swap=providers.settlerAbi.decodeFunctionData('execute',envelope?envelope.data:sent.tx.data),buy=sent.tx.value>0n,event=new Interface(['event Transfer(address indexed from,address indexed to,uint256 value)']).encodeEventLog('Transfer',[buy?SETTLER:tradeAddress,buy?tradeAddress:SETTLER,buy?1001000n:envelope.amount]);logs=[{address:buy?swap.slippage.buyToken:envelope.token,topics:event.topics,data:event.data,transactionHash:arg}];}catch{/* Native withdrawal has no token event. */}}result=!sent||options.unknown||options.approvalUnknown&&sent.approval?null:{status:'0x1',transactionHash:arg,gasUsed:'0x5208',effectiveGasPrice:'0x3b9aca00',blockNumber:'0x10',logs};break;}
      case 'eth_blockNumber':result='0x12';break;
      default:throw Error('Unexpected fixture request '+payload.method);
    }return Response.json({jsonrpc:'2.0',id:1,result});
  });vi.stubGlobal('fetch',fetchMock);return {fetchMock,sends:()=>sends,swapSends:()=>swapSends,signatures};
}
beforeAll(async()=>{
  Object.assign(process.env,{NODE_ENV:'test',VERCEL:'1',DEMO_MODE:'false',APP_URL:'http://localhost:5173',TRADING_CHAIN:'robinhood',CREDENTIAL_ENCRYPTION_KEY:randomBytes(32).toString('hex'),ROBINHOOD_RPC_URL:'https://robinhood-mainnet.g.alchemy.com/v2/test-key',ZEROX_API_KEY:'test-0x-key'});
  pg=await PGlite.create();await migrateEmbedded(pg);socket=new PGLiteSocketServer({db:pg,host:'127.0.0.1',port:15449,maxConnections:20});await socket.start();process.env.DATABASE_URL='postgresql://postgres:postgres@127.0.0.1:15449/postgres';
  ({db}=await import('../server/db.js'));const module=await import('../server/app.js');app=module.app;app.use(module.errorHandler);({executeCommand:execute}=await import('../server/trading.js'));providers=await import('../server/robinhood/providers.js');access=await import('../server/robinhood/access.js');ops=await import('../server/robinhood/operations.js');client=request.agent(app);other=request.agent(app);userId=await login(client,owner);await login(other,foreign);
  const agent=await db.agent.create({data:{creatorId:userId,name:'Robinhood test',description:'Isolated fixture',category:'Monitoring',market:'crypto',tags:['Robinhood'],versions:{create:{number:1,config:{...defaultConfig,network:'robinhood',symbols:[TOKEN]},priceCents:100,setupInstructions:'Fixture only'}}},include:{versions:true}}),instance=await db.instance.create({data:{userId,versionId:agent.versions[0].id}});instanceId=instance.id;await db.tradingWorkspace.create({data:{userId,activeInstanceId:instance.id}});
  const {encrypt}=await import('../server/security.js');channel=await db.personalAgentChannel.create({data:{userId,label:'Fixture',encryptedToken:encrypt('private-fixture-whatsapp-key'),tokenFingerprint:'fixture',ownerId:'user:owner',consentAt:new Date(),createdAt:new Date(Date.now()-1000),leaseToken:'lease',leaseUntil:new Date(Date.now()+3600000)}});
  const review=await post('/owner/review',{address:owner.address,custody:true});expect(review.status,JSON.stringify(review.body)).toBe(200);const verified=await post('/owner/verify',{id:review.body.id,signature:await owner.signMessage(review.body.message)});expect(verified.status,JSON.stringify(verified.body)).toBe(200);tradeAddress=(await access.walletFor(userId)).address;
});
beforeEach(async()=>{
  vi.unstubAllGlobals();headers['X-Vercel-Forwarded-For']=`198.51.100.${++ip}`;process.env.TRADING_CHAIN='robinhood';process.env.ZEROX_API_KEY='test-0x-key';process.env.ROBINHOOD_RPC_URL='https://robinhood-mainnet.g.alchemy.com/v2/test-key';delete process.env.ROBINHOOD_SWAPS_ENABLED;delete process.env.ROBINHOOD_WITHDRAWALS_ENABLED;
  await db.raw('TRUNCATE "RHOperation","RHChallenge","RHPermission","RHWalletBudget","RHAlertEvent","RHAlert","RHDiscovery" CASCADE');await db.agentCommand.deleteMany({where:{userId}});await db.personalAgentChannel.deleteMany({where:{userId,slot:2}});await db.user.update({where:{id:userId},data:{emergencyStop:false}});await db.personalAgentChannel.update({where:{id:channel.id},data:{encryptedToken:channel.encryptedToken,label:channel.label,offset:'0',agentId:null,enabled:true,ownerId:'user:owner',tokenFingerprint:'fixture',leaseToken:'lease',leaseUntil:new Date(Date.now()+3600000),appUrl:null}});await db.tradingWorkspace.update({where:{userId},data:{activeInstanceId:instanceId}});
});
afterEach(()=>vi.unstubAllGlobals());afterAll(async()=>{await db?.close();await socket?.stop();await pg?.close();});
describe('Robinhood amounts and transaction policy',()=>{
  it('keeps owner-review hashes stable across PostgreSQL JSON key ordering',()=>{const a={quote:{transaction:{value:'1',data:'0x',to:TOKEN},side:'BUY'},maxFeeWei:'100',reviewExpiry:'fixed'},b={reviewExpiry:'fixed',maxFeeWei:'100',quote:{side:'BUY',transaction:{to:TOKEN,data:'0x',value:'1'}}};expect(ops.reviewHash(a)).toBe(ops.reviewHash(b));});
  it('uses exact wei values and rejects precision loss or zero',()=>{expect(weiAmount('0.000000000000000001')).toBe(1n);expect(fromWei(1230000000000000000n)).toBe('1.23');expect(()=>weiAmount('0')).toThrow();expect(()=>weiAmount('1.0000001',6)).toThrow();});
  it('creates independently encrypted EVM keys bound to this user and chain',async()=>{const w=await access.walletFor(userId);expect(new Wallet(access.openKey(w)).address.toLowerCase()).toBe(tradeAddress);expect(w.encryptedSecret).not.toContain(access.openKey(w).slice(2));expect(()=>access.openKey({...w,userId:'foreign'})).toThrow();expect(()=>access.openKey({...w,chainId:1})).toThrow();});
  it.each(['recipient','output','minimum','operator','input'])('rejects malicious %s in executable swap calldata',(field)=>{const side=['operator','input'].includes(field)?'SELL':'BUY',bad:any={};bad[field]=field==='minimum'?'1':field==='input'?'2':OTHER;const raw=encodeQuote(tradeAddress,side,'1000000','990000',bad),q={transaction:{...raw.transaction,chainId:4663},sellToken:raw.sellToken,buyToken:raw.buyToken,sellAmount:raw.sellAmount,minBuyAmount:raw.minBuyAmount,settler:SETTLER};expect(()=>providers.validateSwapData(q,tradeAddress)).toThrow();});
  it('rejects a valid-looking quote on another chain or with extra ETH',()=>{const raw=encodeQuote(),q={transaction:{...raw.transaction,chainId:1},sellToken:raw.sellToken,buyToken:raw.buyToken,sellAmount:raw.sellAmount,minBuyAmount:raw.minBuyAmount,settler:SETTLER};expect(()=>providers.validateSwapData(q,tradeAddress)).toThrow();q.transaction.chainId=4663;q.transaction.value='999';expect(()=>providers.validateSwapData(q,tradeAddress)).toThrow();});
  it('rejects a wrong RPC network without any send',async()=>{const net=provider({wrongChain:true});await expect(providers.assetBalance(tradeAddress)).rejects.toThrow('network mismatch');expect(net.sends()).toBe(0);});
  it('accepts the current Settler without consulting previous deployments',async()=>{const net=provider({prevUnavailable:true});expect(await providers.verifySettler(SETTLER)).toBe(SETTLER);const calls=net.fetchMock.mock.calls.map(([,init]:any)=>JSON.parse(init.body||'{}')).filter(p=>p.method==='eth_call'&&p.params[0].to===REGISTRY);expect(calls).toHaveLength(1);expect(calls[0].params[1]).toBe('0x12');expect(net.sends()).toBe(0);});
  it.each([{side:'BUY',holderBuy:false},{side:'BUY',holderBuy:true},{side:'SELL',holderBuy:false}])('validates a registry-verified previous Settler for $side (holder $holderBuy)',async({side,holderBuy})=>{const net=provider({quoteSettler:PREVIOUS,holderBuy});const quote=await providers.quoteSwap(tradeAddress,side,TOKEN,'0.001',100);expect(quote.settler).toBe(PREVIOUS);expect(()=>providers.validateSwapData(quote,tradeAddress)).not.toThrow();const calls=net.fetchMock.mock.calls.map(([,init]:any)=>JSON.parse(init.body||'{}')).filter(p=>p.method==='eth_call'&&p.params[0].to===REGISTRY);expect(calls).toHaveLength(2);expect(calls.every(p=>p.params[1]==='0x12')).toBe(true);expect(net.sends()).toBe(0);});
  it('rejects an arbitrary or predicted next Settler absent from both active registry slots',async()=>{const net=provider({quoteSettler:OTHER,holderBuy:true});await expect(providers.quoteSwap(tradeAddress,'BUY',TOKEN,'0.001',100)).rejects.toThrow('not a verified active 0x Settler');expect(net.sends()).toBe(0);});
  it.each([{registryPaused:true},{badRegistry:true},{currentSettler:'0x'+'0'.repeat(40)}])('does not fall back when current settlement is paused or invalid: %j',async options=>{const net=provider(options);await expect(providers.verifySettler(PREVIOUS)).rejects.toThrow();const currentSelector=new Interface(['function ownerOf(uint256) view returns(address)']).getFunction('ownerOf')!.selector,calls=net.fetchMock.mock.calls.map(([,init]:any)=>JSON.parse(init.body||'{}')).filter(p=>p.method==='eth_call'&&p.params[0].to===REGISTRY);expect(calls).toHaveLength(1);expect(calls[0].params[0].data.startsWith(currentSelector)).toBe(true);expect(net.sends()).toBe(0);});
  it('rejects a previous deployment when its registry lookup fails',async()=>{const net=provider({prevUnavailable:true});await expect(providers.verifySettler(PREVIOUS)).rejects.toThrow();expect(net.sends()).toBe(0);});
});
describe('Robinhood API authorization and funding',()=>{
  it('reads owner and trading balances on Robinhood Chain without transferring funds',async()=>{const net=provider();const result=await client.get('/api/robinhood/funding/status');expect(result.status).toBe(200);expect(result.body).toMatchObject({chainId:4663,ownerAddress:owner.address.toLowerCase(),tradingAddress:tradeAddress,ownerEth:'1',tradingEth:'1',pendingTransactions:'0'});expect((await request(app).get('/api/robinhood/funding/status')).status).toBe(401);expect((await other.get('/api/robinhood/funding/status')).status).toBe(409);expect(net.sends()).toBe(0);});
  it('blocks a new deposit review while the owner has an unresolved on-chain transaction',async()=>{const net=provider({ownerPending:true});const result=await post('/funding/review',{amount:'0.001'});expect(result.status).toBe(409);expect(result.body.error).toContain('unresolved Robinhood Chain transaction');expect(net.fetchMock.mock.calls.some(([,init]:any)=>JSON.parse(init.body||'{}').method==='eth_estimateGas')).toBe(false);expect(net.sends()).toBe(0);});
  it('requires authentication and hides encrypted keys',async()=>{provider();expect((await request(app).get('/api/robinhood/state')).status).toBe(401);const state=await client.get('/api/robinhood/state');expect(state.status,JSON.stringify(state.body)).toBe(200);expect(JSON.stringify(state.body)).not.toContain('encryptedSecret');expect(state.body.wallet.address).toBe(tradeAddress);expect(state.body.providers.chainId).toBe(4663);});
  it('does not allow another owner or replay an owner proof',async()=>{const review=await post('/owner/review',{address:owner.address,custody:true});const wrong=await post('/owner/verify',{id:review.body.id,signature:await foreign.signMessage(review.body.message)});expect(wrong.status).toBe(403);const signed={id:review.body.id,signature:await owner.signMessage(review.body.message)};expect((await post('/owner/verify',signed)).status).toBe(200);expect((await post('/owner/verify',signed)).status).toBe(409);});
  it('prepares only an owner-to-dedicated ETH deposit and never sends it',async()=>{const net=provider();const result=await post('/funding/review',{amount:'0.001'});expect(result.status,JSON.stringify(result.body)).toBe(200);expect(result.body.transaction.from).toBe(owner.address.toLowerCase());expect(result.body.transaction.to).toBe(tradeAddress);expect(BigInt(result.body.transaction.value)).toBe(10n**15n);expect(result.body.transaction.data).toBe('0x');expect(net.sends()).toBe(0);expect((await post('/funding/review',{amount:'0.001',to:foreign.address})).status).toBe(400);});
  it('rejects a deposit larger than the owner balance before gas estimation',async()=>{const net=provider({balance:2299149959884n});const result=await post('/funding/review',{amount:'0.0005'});expect(result.status).toBe(400);expect(result.body.error).toContain('Not enough ETH in the paying Robinhood wallet');expect(result.body.error).not.toContain('RPC');expect(net.fetchMock.mock.calls.some(([,init]:any)=>JSON.parse(init.body||'{}').method==='eth_estimateGas')).toBe(false);expect(net.sends()).toBe(0);});
  it('explains insufficient gas reported by the RPC without exposing the provider response',async()=>{const net=provider({estimateError:'failed with 550000000 gas: insufficient funds for gas * price + value: sensitive provider details'});const result=await post('/funding/review',{amount:'0.0005'});expect(result.status).toBe(400);expect(result.body.error).toContain('Not enough ETH');expect(result.body.error).not.toContain('sensitive provider details');expect(net.sends()).toBe(0);});
  it('keeps unrelated RPC failures separate from insufficient-funds errors',async()=>{const net=provider({estimateError:'Unsupported method'});const result=await post('/funding/review',{amount:'0.0005'});expect(result.status).toBe(502);expect(result.body.error).toContain('could not complete eth_estimateGas');expect(result.body.error).not.toContain('Not enough ETH');expect(net.sends()).toBe(0);});
  it('shows setup required when free provider credentials are absent',async()=>{delete process.env.ZEROX_API_KEY;delete process.env.ROBINHOOD_RPC_URL;const state=await client.get('/api/robinhood/state');expect(state.body.providers.swaps).toBe(false);expect(state.body.native).toBeNull();const trade=await post('/trades/review',{side:'BUY',token:TOKEN,amount:'0.001',maxFeeEth:'0.001',slippageBps:100});expect(trade.status).toBe(503);});
  it('labels website quotes and expired quotes as not submitted, and checking them never sends a transaction',async()=>{const net=provider(),review=await post('/trades/review',{side:'BUY',token:TOKEN,amount:'0.001',maxFeeEth:'0.001',slippageBps:100});expect(review.status).toBe(200);let row=(await client.get('/api/robinhood/state')).body.operations.find((o:any)=>o.id===review.body.id);expect(row.origin).toBe('WEBSITE');expect(row.statusLabel).toBe('Quote only · Not submitted');expect(row.statusDescription).toContain('did not buy or sell');expect(row.txHash).toBeNull();const op=await ops.operationFor(userId,review.body.id);await db.raw('UPDATE "RHOperation" SET data=$1::jsonb WHERE id=$2',[JSON.stringify({...op.data,reviewExpiry:new Date(Date.now()-1000).toISOString()}),op.id]);const checked=await post('/operations/'+op.id+'/check');expect(checked.body.statusLabel).toBe('Quote expired · Not submitted');expect(checked.body.txHash).toBeNull();expect(checked.body.status).toBe('PREVIEW');expect(net.sends()).toBe(0);});
  it('keeps discovery available without Alchemy or 0x credentials',async()=>{provider();delete process.env.ZEROX_API_KEY;delete process.env.ROBINHOOD_RPC_URL;const data=await request(app).get('/api/robinhood/tokens?q='+TOKEN);expect(data.status).toBe(200);expect(data.body.tokens[0].address).toBe(TOKEN);expect(data.body.tokens[0].symbol).toBe('TST');});
  it('requires fresh original-owner approval and keeps trading separate from withdrawals',async()=>{provider();await grant();const state=await client.get('/api/robinhood/state');expect(state.body.tradePermission.active).toBe(true);expect(state.body.withdrawalPermission).toBeNull();expect((await chat('Withdraw 0.001 ETH')).command.reply).toContain('separate WhatsApp withdrawal');});
  it('rejects a permission approved from a different workspace session',async()=>{const review=await post('/permission/review',limits);const response=await other.post('/api/robinhood/permission/approve').set(headers).send({kind:'TRADE',id:review.body.id,signature:await owner.signMessage(review.body.message)});expect(response.status).toBe(409);});
});
describe('Robinhood WhatsApp execution and spending controls',()=>{
  it.each(['BUY','SELL'] as const)('explains missing executable liquidity for %s without signing, charging gas or retrying',async side=>{const net=provider({noLiquidity:true});await grant();const result=await chat(side==='BUY'?'Buy 0.001 ETH of '+TOKEN:'Sell 1 of '+TOKEN);expect(result.command.reply).toContain('No executable 0x route');expect(result.command.reply).toContain('DEX Screener listing does not guarantee');const op=(await ops.operationList(userId))[0];expect(op.status).toBe('REJECTED');expect(op.txHash).toBeNull();expect(op.approvalHash).toBeNull();await chat('Check status');expect(net.fetchMock.mock.calls.filter(([url]:any)=>String(url).startsWith('https://api.0x.org/'))).toHaveLength(1);expect(net.sends()).toBe(0);});
  it('keeps malformed provider data distinct from unavailable liquidity',async()=>{const net=provider({malformedQuote:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('incomplete or unsupported quote');expect(result.command.reply).not.toContain('No executable 0x route');expect(net.sends()).toBe(0);});
  it.each(['BUY','SELL'] as const)('rejects a 0x-reported %s balance issue before approval or signing',async side=>{const net=provider({quoteBalanceIssue:true});await grant();const result=await chat(side==='BUY'?'Buy 0.001 ETH of '+TOKEN:'Sell 1 of '+TOKEN);expect(result.command.reply).toContain(side==='BUY'?'Not enough ETH':'Not enough tokens');expect(net.sends()).toBe(0);});
  it('bounds gas estimation by signed consent and available ETH using the same buffered price as simulation',async()=>{const balance=2n*10n**15n,net=provider({requireGasBounds:true,balance});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');const requests=net.fetchMock.mock.calls.map(([,init]:any)=>JSON.parse(init.body||'{}')),estimate=requests.find(p=>p.method==='eth_estimateGas').params[0],simulation=requests.find(p=>p.method==='eth_call'&&p.params[0].gas).params[0];expect(BigInt(estimate.gasPrice)).toBe(1250000000n);expect(BigInt(estimate.gas)*BigInt(estimate.gasPrice)).toBeLessThanOrEqual(10n**15n);expect(BigInt(estimate.value)+BigInt(estimate.gas)*BigInt(estimate.gasPrice)).toBeLessThanOrEqual(balance);expect(simulation.gasPrice).toBe(estimate.gasPrice);expect(BigInt(simulation.gas)).toBeLessThanOrEqual(BigInt(estimate.gas));expect(net.sends()).toBe(1);});
  it.each([
    {estimateError:'execution reverted: private provider response',estimateErrorCode:3,expected:'simulation reverted on-chain'},
    {estimateError:'execution reverted',estimateErrorCode:3,estimateErrorData:'0xcd21db4f'+'00'.repeat(32),expected:'swap route expired on-chain'},
    {estimateError:'max fee per gas less than block base fee: private response',expected:'network gas price changed'},
    {estimateError:'gas required exceeds allowance (40000)',expected:'Gas simulation could not fit'},
  ])('reports $expected accurately and never submits after rejected estimation',async({expected,...failure})=>{const net=provider(failure);await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain(expected);expect(result.command.reply).not.toContain('private');expect(result.command.reply).not.toContain('RPC could not complete');await chat('Check status');expect(net.sends()).toBe(0);});
  it('does not bypass a reverted final simulation even when gas estimation succeeded',async()=>{const net=provider({simulationRevert:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('simulation reverted on-chain');expect(net.sends()).toBe(0);});
  it('includes metadata, quote protection and receipt-derived quantities and gas without confusing the quote with a fill',async()=>{const net=provider();await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN),reply=result.command.reply;expect(reply).toContain('Token: Test token (TST)');expect(reply).toContain('Network: Robinhood Chain · 4663');expect(reply).toContain('Quoted expected receive: 1 TST');expect(reply).toContain('Minimum receive (quote protection): 0.99 TST');expect(reply).toContain('Net TST change (receipt transfers): 1.001');expect(reply).toContain('Slippage limit: 1%');expect(reply).toContain('Swap gas paid: 0.000021 ETH');expect(reply).toContain('Approved gas cap: 0.001 ETH');expect(reply).toContain('Block: 16');expect(reply).toContain('Portfolio: http://localhost:5173/portfolio');const checked=await chat('Check status');expect(checked.command.reply).toContain('Net TST change (receipt transfers): 1.001');expect(net.sends()).toBe(1);});
  it('reports both approval and swap gas for token sales, with a signed receipt token change',async()=>{const net=provider();await grant();const result=await chat('Sell 1 of '+TOKEN);expect(result.command.reply).toContain('Net TST change (receipt transfers): -1');expect(result.command.reply).toContain('Approval gas paid: 0.000021 ETH');expect(result.command.reply).toContain('Swap gas paid: 0.000021 ETH');expect(result.command.reply).toContain('Quoted expected receive: 0.001 ETH');expect(net.sends()).toBe(2);});
  it('enriches historical confirmed status read-only when receipt details were not previously stored',async()=>{const net=provider();await grant();await chat('Buy 0.001 ETH of '+TOKEN);await db.raw('UPDATE "RHOperation" SET data=data-\'receipt\' WHERE "userId"=$1',[userId]);const checked=await chat('Check status');expect(checked.command.reply).toContain('Net TST change (receipt transfers): 1.001');expect(net.sends()).toBe(1);});
  it('executes a native-ETH AllowanceHolder buy during the documented 0x deployment dwell period',async()=>{const net=provider({quoteSettler:PREVIOUS,holderBuy:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');expect(net.swapSends()).toBe(1);expect([...net.signatures.values()][0].tx.to.toLowerCase()).toBe(HOLDER);});
  it('executes a token sale through the verified previous Settler with an exact AllowanceHolder approval',async()=>{const net=provider({quoteSettler:PREVIOUS});await grant();const result=await chat('Sell 1 of '+TOKEN);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');expect(net.sends()).toBe(2);expect(net.swapSends()).toBe(1);});
  it('rechecks registry membership before signing and blocks a deployment that is no longer current or previous',async()=>{const options={quoteSettler:PREVIOUS,previousSettler:PREVIOUS,onNonce:async()=>{options.previousSettler=OTHER;}},net=provider(options);await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('NOT EXECUTED');expect(result.command.reply).toContain('not a verified active 0x Settler');expect(net.sends()).toBe(0);});
  it('blocks a previously reviewed deployment if settlement is paused before signing',async()=>{const options={quoteSettler:PREVIOUS,registryPaused:false,onNonce:async()=>{options.registryPaused=true;}},net=provider(options);await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('NOT EXECUTED');expect(net.sends()).toBe(0);});
  it('allows a new supported token outside the saved agent list after any-token approval',async()=>{const net=provider();await grant();const result=await chat('Buy 0.001 ETH of '+OTHER);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');expect(result.command.reply).toContain(OTHER);expect(net.sends()).toBe(1);});
  it('supports a one-use owner-signed website trade without granting ongoing access',async()=>{const net=provider(),review=await post('/trades/review',{side:'BUY',token:TOKEN,amount:'0.001',maxFeeEth:'0.001',slippageBps:100,source:'TRADING'});expect(review.status,JSON.stringify(review.body)).toBe(200);const proof=review.body.review,result=await post('/trades/execute',{id:proof.id,signature:await owner.signMessage(proof.message)});expect(result.status,JSON.stringify(result.body)).toBe(200);expect(result.body.status).toBe('CONFIRMED');expect(await access.latestPermission(userId,'TRADE')).toBeNull();expect((await post('/trades/execute',{id:proof.id,signature:await owner.signMessage(proof.message)})).status).toBe(409);expect(net.sends()).toBe(1);});
  it('buys a supported token with one grant and deduplicates the original message',async()=>{const net=provider();await grant();const id=randomUUID(),result=await chat('Buy 0.001 ETH of '+TOKEN,id);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');expect(net.sends()).toBe(1);const again=await chat('Buy 0.001 ETH of '+TOKEN,id);expect(again.duplicate).toBe(true);expect(net.sends()).toBe(1);const check=await chat('Check trade');expect(check.command.reply).toContain(result.command.id);expect(net.sends()).toBe(1);});
  it('checks the executable minimum output before signing',async()=>{const net=provider({badMinimum:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('NOT EXECUTED');expect(net.sends()).toBe(0);});
  it('rejects provider fees beyond the signed 1% ceiling',async()=>{const net=provider({feeTooHigh:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('fee exceeds');expect(net.sends()).toBe(0);});
  it('reserves gas in the total per-trade budget',async()=>{const net=provider();await grant({perLimitEth:'0.001',maxFeeEth:'0.0001'});const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('reserved gas');expect(net.sends()).toBe(0);});
  it('does not reset daily spending when a grant is replaced',async()=>{const net=provider();await grant({perLimitEth:'0.003',dailyEth:'0.003'});await chat('Buy 0.001 ETH of '+TOKEN);expect(net.sends()).toBe(1);await grant({perLimitEth:'0.003',dailyEth:'0.003'});const again=await chat('Buy 0.001 ETH of '+TOKEN);expect(again.command.reply).toContain('daily spending budget');expect(net.sends()).toBe(1);});
  it('enforces a restricted token list before submission',async()=>{const net=provider();await grant({tokenScope:'SELECTED_TOKENS',tokens:[OTHER]});const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('outside the signed');expect(net.sends()).toBe(0);});
  it('sells with a narrowly bounded allowance and only then executes the swap',async()=>{const net=provider();await grant();const result=await chat('Sell 10 of '+TOKEN);expect(result.command.reply).toContain('ROBINHOOD CONFIRMED');expect(net.sends()).toBe(2);expect(net.swapSends()).toBe(1);const first=[...net.signatures.values()][0];expect(first.tx.to.toLowerCase()).toBe(TOKEN);const call=providers.erc20.decodeFunctionData('approve',first.tx.data);expect(call[0].toLowerCase()).toBe(HOLDER);expect(call[1]).toBe(10000000n);});
  it('refuses to sell more than the real dedicated-wallet token balance',async()=>{const net=provider({tokenBalance:1n});await grant();const result=await chat('Sell 100 of '+TOKEN);expect(result.command.reply).toContain('Not enough tokens');expect(net.sends()).toBe(0);});
  it('does not repeat an unknown submission through Check trade or a fresh command',async()=>{const net=provider({unknown:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('CONFIRMATION PENDING');expect(net.sends()).toBe(1);await chat('Check trade');await chat('Buy 0.001 ETH of '+TOKEN);expect(net.sends()).toBe(1);});
  it('recognizes Check status and reports the rejected WhatsApp request without submitting it',async()=>{const net=provider({badMinimum:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN),checked=await chat('check status');expect(checked.command.reply).toContain('READ-ONLY STATUS');expect(checked.command.reply).toContain(result.command.id);expect(checked.command.reply).toContain('NOT EXECUTED');expect(net.sends()).toBe(0);});
  it('keeps Check status bound to the original WhatsApp request even when a newer website quote exists',async()=>{const net=provider();await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN),quote=await post('/trades/review',{side:'BUY',token:OTHER,amount:'0.002',maxFeeEth:'0.001',slippageBps:100});expect(quote.status).toBe(200);for(const text of ['Check status','Check my status','Check status '+result.command.id]){const checked=await chat(text);expect(checked.command.reply).toContain(result.command.id);expect(checked.command.reply).not.toContain(quote.body.id);expect(checked.command.reply).toContain('ROBINHOOD CONFIRMED');}expect(net.sends()).toBe(1);});
  it('keeps Check status read-only for unknown submissions and rejects unrelated website references',async()=>{const net=provider({unknown:true});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN),checked=await chat('Check status');expect(checked.command.reply).toContain('CONFIRMATION PENDING');expect(checked.command.reply).toContain(result.command.id);const unrelated=await chat('Check status '+randomUUID());expect(unrelated.command.reply).toContain('NO MATCHING REQUEST');expect(net.sends()).toBe(1);});
  it('makes website quote-only history explicit without treating it as a WhatsApp purchase',async()=>{const net=provider();const quote=await post('/trades/review',{side:'BUY',token:TOKEN,amount:'0.001',maxFeeEth:'0.001',slippageBps:100});expect(quote.status).toBe(200);const history=await chat('Trade history'),check=await chat('Check status '+quote.body.id);expect(history.command.reply).toContain('Quote only · Not submitted');expect(check.command.reply).toContain('NO MATCHING REQUEST');expect(net.sends()).toBe(0);});
  it('does not show a historical receipt for a new review-only request',async()=>{const net=provider();await grant();await chat('Buy 0.001 ETH of '+TOKEN);await chat('Revoke trading');const review=await chat('Buy 0.002 ETH of '+OTHER);expect(review.command.reply).toContain('NOT SUBMITTED');const status=await chat('Check trade');expect(status.command.reply).toContain('NO WHATSAPP ORDER SUBMITTED');expect(status.command.reply).toContain(review.command.id);expect(status.command.reply).not.toContain('ROBINHOOD CONFIRMED');expect(net.sends()).toBe(1);});
  it('invalidates grants after a paired connection change',async()=>{const net=provider();await grant();await db.personalAgentChannel.update({where:{id:channel.id},data:{tokenFingerprint:'changed'}});const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('connection changed');expect(net.sends()).toBe(0);});
  it('blocks expired, revoked and emergency-stopped execution',async()=>{const net=provider(),id=await grant();await db.raw('UPDATE "RHPermission" SET "expiresAt"=$1 WHERE id=$2',[new Date(Date.now()-1000),id]);expect((await chat('Buy 0.001 ETH of '+TOKEN)).command.reply).toContain('expired');await grant();await chat('Stop all');expect((await chat('Buy 0.001 ETH of '+TOKEN)).command.reply).not.toContain('CONFIRMED');expect(net.sends()).toBe(0);});
  it('rechecks revocation after network preparation and before signing',async()=>{let once=false;const net=provider({onNonce:async()=>{if(!once){once=true;await db.raw('UPDATE "RHPermission" SET "revokedAt"=CURRENT_TIMESTAMP WHERE "userId"=$1',[userId]);}}});await grant();const result=await chat('Buy 0.001 ETH of '+TOKEN);expect(result.command.reply).toContain('NOT EXECUTED');expect(net.sends()).toBe(0);});
  it('does not honor database edits that expand the original signed budgets',async()=>{const net=provider();const id=await grant();await db.raw('UPDATE "RHPermission" SET "perLimitWei"=$1,"dailyLimitWei"=$2 WHERE id=$3',['100000000000000000','200000000000000000',id]);const result=await chat('Buy 0.02 ETH of '+TOKEN);expect(result.command.reply).toContain('original signed consent');expect(net.sends()).toBe(0);});
  it('uses exact current token identity in information commands and never sends a trade',async()=>{const net=provider();for(const text of ['Balance','Portfolio','Token '+TOKEN,'Trade history','My limits']){const result=await chat(text);expect(result.command.status).toBe('COMPLETED');}expect(net.sends()).toBe(0);});
});
